spec.expr:
(
  count(ALERTS{connector_id="NvidiaDCGMExporter", alertstate="firing", severity="warning", alertname=~"MetricsHub-(GPU|Hardware).*", alertname!~"MetricsHub-Hardware-Device-Status-.*", host_name=~"$model_hosts"})
  or vector(0)
)
+ on()
(
  sum(
    max by (host_name, id) (
      hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="degraded"} == 1
    )
  )
  or vector(0)
)
+ on()
(
  sum(
    max by (host_name, id) (
      hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network|temperature", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state=~"degraded|predicted_failure"} == 1
    )
  )
  or vector(0)
)

count(
  sum by (host_name, id) (
    increase(hw_gpu_throttle_time_seconds_total{connector_id="NvidiaDCGMExporter", hw_gpu_nvidia_mig_instance_id="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", hw_gpu_throttle_reason=~"hardware-thermal|software-thermal|hardware-power-brake"}[$__range])
  ) > 0
)
or vector(0)

label_join(
  min by (host_name, id) (
    hw_temperature_limit_celsius{connector_id="NvidiaDCGMExporter", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", sensor_location="gpu", limit_type=~"high.degraded|high.critical"}
  )
  - on (host_name, id) group_right ()
  max by (host_name, hw_gpu_index, hw_gpu_model, hw_gpu_nvidia_mig_instance_id, hw_gpu_pci_bus_id, id) (
    hw_temperature_celsius{connector_id="NvidiaDCGMExporter", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", sensor_location="gpu"}
  ),
  "id", "/", "host_name", "id"
)

topk(10,
  max by (host_name, hw_gpu_index, hw_gpu_model, id) (
    hw_power_watts{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_nvidia_mig_instance_id="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model"}
  )
  / on (host_name, id) group_left ()
  max by (host_name, id) (
    hw_power_limit_watts{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_nvidia_mig_instance_id="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model"}
  )
)

count(
  max by (host_name, id) (
    hw_gpu_fabric_condition_active_ratio{connector_id="NvidiaDCGMExporter", hw_gpu_nvidia_mig_instance_id="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model"} == 1
  )
  or
  max by (host_name, id) (
    hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem=~"fabric|fabric-manager", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state=~"degraded|failed"} == 1
  )
)
or vector(0)

0 * count(
  hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="ok"}
  or hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state="ok"}
)
unless on ()
(
  count(
max by (host_name, id, name, hw_gpu_subsystem) (
  2 * ((max_over_time(hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="failed"}[$__interval]) or hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="failed"}) == 1)
  or ((max_over_time(hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state=~"degraded|predicted_failure"}[$__interval]) or hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state=~"degraded|predicted_failure"}) == 1)
  or 0 * (hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="ok"} == 1)
)
and on (host_name, id, name, hw_gpu_subsystem)
(
  max by (host_name, id, name, hw_gpu_subsystem) (max_over_time(hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state=~"failed|degraded|predicted_failure"}[$__range] @ end())) == 1
)
  )
  or
  count(
max by (host_name, id, name) (
  2 * ((max_over_time(hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state="failed"}[$__interval]) or hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state="failed"}) == 1)
  or ((max_over_time(hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state=~"degraded|predicted_failure"}[$__interval]) or hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state=~"degraded|predicted_failure"}) == 1)
  or 0 * (hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state="ok"} == 1)
)
and on (host_name, id, name)
(
  max by (host_name, id, name) (max_over_time(hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state=~"failed|degraded|predicted_failure"}[$__range] @ end())) == 1
)
  )
)

0 * count(hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem="", hw_gpu_nvidia_mig_instance_id="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="present"} == 1) - 1
unless on ()
count(
  hw_status{connector_id="NvidiaDCGMExporter", hw_type="gpu", hw_gpu_subsystem!="", host_name=~"$host_name", hw_gpu_model=~"$gpu_model", state="ok"}
  or hw_status{connector_id="NvidiaDCGMExporter", hw_type=~"other_device|network", device_type=~"NVSwitch|NVLink", host_name=~"$model_hosts", state="ok"}
)
